import{_ as a,o as r,c as o,a0 as t}from"./chunks/framework.DqMqoJl9.js";const p=JSON.parse('{"title":"Territory Docs","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function c(d,e,l,s,n,_){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="territory-docs" tabindex="-1">Territory Docs <a class="header-anchor" href="#territory-docs" aria-label="Permalink to &quot;Territory Docs&quot;">​</a></h1><p>Документация системы паспортного учёта «Паспорт».</p><h2 id="навигация-по-разделам" tabindex="-1">Навигация по разделам <a class="header-anchor" href="#навигация-по-разделам" aria-label="Permalink to &quot;Навигация по разделам&quot;">​</a></h2><ul><li><a href="./database/">База данных и модели</a> — Структура БД (Oracle), ядро (<code>CORE_*</code>), справочники (<code>DICT_*</code>), модули (РП, ЗП, Регистрация, Миграция), связи и ER-диаграммы.</li><li><a href="./source-code/">Исходный код и модели</a> — Архитектура проектов (<code>Umms.*</code>), основные модули ПО СС/ПО МС, сценарии (№1, USB-обмен), сопоставление моделей кода с таблицами БД.</li><li><a href="./api/">API эндпоинты</a> — Спецификация API (JSON), эндпоинты (лица, документы, миграция, снятие с учета), сверка полей запросов с полями таблиц БД, особенности валидации и отката.</li></ul><h2 id="общая-информация" tabindex="-1">Общая информация <a class="header-anchor" href="#общая-информация" aria-label="Permalink to &quot;Общая информация&quot;">​</a></h2><p>Информационная база системы паспортного учёта предназначена для автоматизации учета граждан, документов, регистрации и миграции. Модель реализована в Oracle, включает 401 таблицу (44 таблицы ядра <code>CORE_*</code>, 104 таблицы справочников <code>DICT_*</code>, остальные относятся к модулям предметной области).</p><ul><li><strong>Формат обмена</strong>: JSON (при обмене между сервисами), прямые SQL-запросы к БД (при работе АРМ МС).</li><li><strong>Версия API</strong>: 1.0</li><li><strong>Оптимистическая блокировка</strong>: Используется поле <code>VERSION</code> (NUMBER) во всех таблицах ядра и миграции.</li></ul>',7)])])}const u=a(i,[["render",c]]);export{p as __pageData,u as default};
